"""
title: Sandbox E2B
description: Executa código Python numa sandbox segura na nuvem (E2B). Use para rodar, testar e validar código, fazer cálculos, processar dados e conferir resultados reais.
version: 1.2.0
"""

import os


class Tools:
    class Valves:
        # Editável pelo admin: Workspace > Ferramentas > Sandbox E2B > Valves
        E2B_API_KEY: str = ""
        E2B_TIMEOUT: int = 600

    class UserValves:
        # Espelho das Valves: garante o editor de valves no painel; se o
        # Open WebUI aplicar as valves do usuário, os nomes são os mesmos.
        E2B_API_KEY: str = ""
        E2B_TIMEOUT: int = 600

    def __init__(self):
        self.valves = self.Valves()
        self.sbx = None

    def _get_sandbox(self):
        try:
            from e2b_code_interpreter import Sandbox
        except ImportError:
            from e2b import Sandbox
        key = (getattr(self.valves, "E2B_API_KEY", "") or "").strip() \
            or os.environ.get("E2B_API_KEY", "")
        if not key:
            raise RuntimeError(
                "Chave da E2B nao configurada. No painel: Workspace > Ferramentas > "
                "Sandbox E2B > Valves > E2B_API_KEY (crie a conta em e2b.dev e copie a API key)."
            )
        if self.sbx is None:
            timeout_s = int(getattr(self.valves, "E2B_TIMEOUT", 600) or 600)
            create = getattr(Sandbox, "create", None)
            if create is not None:
                try:
                    self.sbx = create(api_key=key, timeout=timeout_s)
                except TypeError:
                    self.sbx = Sandbox(api_key=key, timeout=timeout_s)
            else:
                self.sbx = Sandbox(api_key=key, timeout=timeout_s)
        return self.sbx

    def e2b_run_python(self, code: str) -> str:
        """
        Executa código Python em uma sandbox isolada na nuvem (E2B) e devolve a saída real.
        Use SEMPRE que precisar rodar, testar ou validar código Python, fazer cálculos,
        processar dados ou gerar gráficos. Imagens não são exibidas: se gerar um gráfico,
        imprima também os números principais no stdout.

        :param code: Código Python completo para executar na sandbox.
        :return: Saída da execução: resultado, stdout, stderr e erros.
        """
        try:
            return self._run(code)
        except Exception:
            # sandbox pode ter expirado: recria e tenta mais uma vez
            self.sbx = None
            try:
                return self._run(code)
            except Exception as e:
                return "ERRO E2B: " + str(e)

    def _run(self, code: str) -> str:
        sbx = self._get_sandbox()
        try:
            sbx.keep_alive(600)
        except Exception:
            pass
        runner = getattr(sbx, "run_code", None) or getattr(sbx, "runCode")
        ex = runner(code)
        parts = []
        for r in getattr(ex, "results", None) or []:
            t = getattr(r, "text", None)
            if t:
                parts.append("RESULTADO:\n" + t)
        logs = getattr(ex, "logs", None)
        out = "\n".join(getattr(logs, "stdout", None) or [])
        err = "\n".join(getattr(logs, "stderr", None) or [])
        if out:
            parts.append("STDOUT:\n" + out)
        if err:
            parts.append("STDERR:\n" + err)
        error = getattr(ex, "error", None)
        if error is not None:
            tb = getattr(error, "traceback", None) or (
                str(getattr(error, "name", "")) + ": " + str(getattr(error, "value", ""))
            )
            parts.append("ERRO DE EXECUCAO:\n" + tb)
        if not parts:
            parts.append("(executado sem saida)")
        return "\n\n".join(parts)
